    #[test]
    fn test_bitwise_or() {
        let a = vec![0b0000_0001, 0b1010_1010, 0b1111_0000];
        let b = vec![0b0000_0010, 0b0101_0101, 0b0000_1111];
        let result = bitwise_or(a, b);
        assert_eq!(
            result,
            vec![0b0000_0011, 0b1111_1111, 0b1111_1111]
        );
    }

